WITH order_summary AS (SELECT order_id, MAX(amount) - MIN(amount) AS amount_range, ROUND(AVG(amount), 2) AS avg_amount FROM payments WHERE method IS NOT NULL GROUP BY order_id) SELECT orders.channel, order_summary.amount_range, order_summary.avg_amount FROM orders LEFT JOIN order_summary ON orders.id = order_summary.order_id WHERE order_summary.amount_range > 28 ORDER BY orders.channel, order_summary.avg_amount
